section.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/django-celery.json",
  "type": "object",
  "title": "Django + Celery Background Jobs",
  "required": [
    "task_name",
    "business_key",
    "idempotency",
    "queue",
    "max_retries",
    "backoff_base_seconds",
    "backoff_jitter",
    "soft_time_limit",
    "time_limit",
    "dispatch_mode",
    "dlq_strategy",
    "dlq_queue",
    "alerting_channel"
  ],
  "additionalProperties": false,
  "properties": {
    "task_name": {
      "type": "string",
      "minLength": 1,
      "pattern": "^[a-z][a-z0-9_.]+$",
      "description": "Explicit dotted task name passed to name= on the decorator."
    },
    "business_key": {
      "type": "string",
      "minLength": 1,
      "description": "Name of the idempotency-key argument."
    },
    "idempotency": {
      "type": "string",
      "enum": [
        "idempotency_key",
        "db_upsert",
        "check_before_act",
        "natural_key"
      ],
      "description": "Declared idempotency strategy guarding the business key."
    },
    "queue": {
      "type": "string",
      "minLength": 1,
      "description": "Explicit queue name; never the default queue."
    },
    "max_retries": {
      "type": "integer",
      "minimum": 0,
      "maximum": 5,
      "description": "Bounded retry count; ≤5."
    },
    "backoff_base_seconds": {
      "type": "integer",
      "minimum": 1,
      "description": "Exponential backoff base; ≥1."
    },
    "backoff_jitter": {
      "type": "string",
      "enum": [
        "none",
        "full",
        "equal"
      ],
      "description": "Jitter style."
    },
    "retry_backoff": {
      "type": "boolean",
      "description": "Exponential backoff enabled on the decorator."
    },
    "retry_jitter": {
      "type": "boolean",
      "description": "Jitter enabled on the decorator."
    },
    "soft_time_limit": {
      "type": "integer",
      "minimum": 1,
      "description": "Seconds before SoftTimeLimitExceeded is raised inside the task."
    },
    "time_limit": {
      "type": "integer",
      "minimum": 1,
      "description": "Seconds before the worker process is hard-killed."
    },
    "dispatch_mode": {
      "type": "string",
      "enum": [
        "on_commit",
        "outside_transaction"
      ],
      "description": "Where dispatch happens."
    },
    "dlq_strategy": {
      "type": "string",
      "enum": [
        "dlq",
        "failure_record",
        "alert_only"
      ],
      "description": "What happens once retries are exhausted."
    },
    "dlq_queue": {
      "type": "string",
      "minLength": 1,
      "description": "Dead-letter queue name."
    },
    "alerting_channel": {
      "type": "string",
      "minLength": 1,
      "description": "Pager channel for DLQ alerts."
    }
  }
}
